async function carregarUsuarios(){try{const a=await fetch("/api/admin/usuarios");if(403===a.status||401===a.status)return alert("Você não tem permissão para acessar esta página."),void(window.location.href="/");const e=await a.json();e.sucesso&&renderizarUsuarios(e.dados)}catch{alert("Erro ao carregar dados. Tente novamente.")}}function criarCelula(a){const e=document.createElement("td");return e.textContent=a??"",e}function renderizarUsuarios(a){const e=document.querySelector("#tabelaUsuarios tbody");if(e.replaceChildren(),!a.length){const a=e.insertRow().insertCell();return a.colSpan=7,void(a.textContent="Nenhum usuário encontrado.")}for(const t of a){const a=document.createElement("tr");a.append(criarCelula(t.id),criarCelula(t.nome),criarCelula(t.email),criarCelula(t.saldo_moedas),criarCelula(t.status),criarCelula(t.ganhos_afiliado??0));const o=document.createElement("td"),n=document.createElement("button");n.className="btn btn-warning btn-sm fw-bold",n.textContent="+ Dar Moedas",n.addEventListener("click",()=>darTokens(t.id)),o.className="text-end",o.append(n),a.append(o),e.append(a)}}async function darTokens(a){const e=prompt(`Quantos moedas deseja adicionar ao usuário ID ${a}?`),t=parseInt(e,10);if(!(!e||isNaN(t)||t<=0))try{const e=await fetch("/api/admin/usuarios/moedas",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({usuarioId:a,quantidade:t})}),o=await e.json();o.sucesso?(alert("Moedas adicionados com sucesso!"),carregarUsuarios()):alert(`Erro: ${o.erro}`)}catch{alert("Erro de conexão ao adicionar moedas.")}}document.addEventListener("DOMContentLoaded",carregarUsuarios);